import React, { useState } from 'react';
import Sidebar from '../components/Sidebar';
import TopBar from '../components/TopBar';
import StatsRow from '../components/StatsRow';
import CameraGrid from '../components/CameraGrid';
import DetectionSummary from '../components/DetectionSummary';
import ChartsRow from '../components/ChartsRow';
import SystemPerf from '../components/SystemPerf';
import AlertsPanel from '../components/AlertsPanel';
import ThresholdPanel from '../components/ThresholdPanel';
import RecordingsPanel from '../components/RecordingsPanel';
import CamerasPage from './CamerasPage';
import GraphsPage from './GraphsPage';

// Pages jahan right panel show nahi hoga
const FULL_WIDTH_PAGES = ['Cameras', 'Graphs'];

export default function Dashboard() {
  const [activePage, setActivePage] = useState('Dashboard');

  const isFullWidth = FULL_WIDTH_PAGES.includes(activePage);

  const renderMain = () => {
    switch (activePage) {
      case 'Cameras':
        return <CamerasPage />;
      case 'Graphs':
        return <GraphsPage />;
      default:
        return (
          <div style={{ flex: 1, overflowY: 'auto', padding: '10px 12px' }}>
            <CameraGrid />
            <DetectionSummary />
            <ChartsRow />
            <SystemPerf />
          </div>
        );
    }
  };

  return (
    <div style={{
      display:             'grid',
      gridTemplateColumns: isFullWidth
        ? '200px 1fr'           // Full width — no right panel
        : '200px 1fr 280px',    // Normal — with right panel
      height:   '100vh',
      overflow: 'hidden',
      background: '#0a0e1a'
    }}>

      {/* SIDEBAR */}
      <Sidebar
        activePage={activePage}
        setActivePage={setActivePage}
      />

      {/* MAIN */}
      <div style={{
        display:       'flex',
        flexDirection: 'column',
        overflow:      'hidden'
      }}>
        <TopBar />
        <StatsRow />
        {renderMain()}
      </div>

      {/* RIGHT PANEL — sirf dashboard pe */}
      {!isFullWidth && (
        <div style={{
          background:    '#111827',
          borderLeft:    '1px solid #1e2d47',
          display:       'flex',
          flexDirection: 'column',
          overflow:      'hidden'
        }}>
          <AlertsPanel />
          <ThresholdPanel />
          <RecordingsPanel />
        </div>
      )}

    </div>
  );
}
